class Element{constructor(id){this.id=id;this.textContent='';this.innerHTML='';this.hidden=false;this.disabled=false;this.files=[];}querySelector(){return null;}}
function documentFixture(hash){const nodes=new Map(),events={};function make(id){const el=new Element(id);let html='';Object.defineProperty(el,'innerHTML',{get:()=>html,set:value=>{html=value;if(id==='task-workspace')nodes.clear();for(const m of value.matchAll(/<[^>]+\bid="([^"]+)"[^>]*>/g)){const n=make(m[1]);n.hidden=/\shidden(?:\s|>)/.test(m[0]);n.disabled=/\sdisabled(?:\s|>)/.test(m[0]);n.open=/\sopen(?:\s|>)/.test(m[0]);nodes.set(n.id,n);}}});return el;}const host=make('task-workspace');const location={hash,href:'https://example.org/run.html'+hash};const win={location,addEventListener:(name,fn)=>events[name]=fn,removeEventListener:name=>delete events[name]};return{defaultView:win,host,getElementById:id=>id==='task-workspace'?host:nodes.get(id)||null,events};}

async function makeTask(title='Fixture <safe>'){return E.prepare({title,alphabet,pages:[{id:'lp2-15',text:'ᚠᚠ-ᚢ\nᚦ'}],steps:[{op:'reverse',unit:'word'}],criterion:{kind:'measurement'}},webcrypto)}
