async function controlHandoffRaceTests(){
 for(const authored of [false,true])for(const stale of ['cancel','navigation','destroy']){
  const task=await makeTask('Synthetic control handoff race'),suite=await PC.prepare(task,webcrypto);
  const controlTask=await E.prepare({...task,title:'Synthetic authored handoff check',criterion:{kind:'exact-prefix',values:[0,0,1,2]}},webcrypto);
  const cases=authored?[{task:controlTask}]:suite.cases,lastResult=E.stable(E.run(cases.at(-1).task));
  const origins=authored?[{origin:{recordId:'handoff-fixture',followupId:'fixed-control',recordSha256:'a'.repeat(64),protocolSha256:'b'.repeat(64)},control:{label:'Synthetic positive control',task:controlTask,expected_result_sha256:createHash('sha256').update(lastResult).digest('hex')},question:'Known synthetic start',scopeChange:'Same synthetic operation',limitation:'No manuscript decryption claim'}]:[];
  let armed=false,handedOff=false,f;
  const cryptoAPI={subtle:{digest(algorithm,bytes){const result=webcrypto.subtle.digest(algorithm,bytes);if(!armed||new TextDecoder().decode(bytes)!==lastResult)return result;armed=false;return{then(resolve,reject){result.then(value=>{resolve(value);queueMicrotask(()=>{handedOff=true;assert(f.doc.getElementById('control-status').textContent.includes('passed'),'The control callee has completed before cancellation is queued at caller handoff');if(stale==='cancel')f.click('cancel-run');else if(stale==='navigation')f.doc.defaultView.location.hash='#idea='+proposalId;else f.app.destroy();});},reject);}};}}};
  f=await fixture({task,manualControls:true,cryptoAPI,get:async()=>Response.json({...projection(task),origins})});
  try{
   assert(f.doc.getElementById('result-file'),(authored?'authored':'generic')+' '+f.doc.host.innerHTML);await f.upload(E.run(task));const selected=f.app.getState().selected,pending=f.click('run-browser');
   for(let i=0;i<cases.length;i++){await until(()=>f.executions.length===i+1);if(i===cases.length-1)armed=true;f.executions[i].resolve(E.run(cases[i].task));}
   await until(()=>handedOff);await turn();
   // Resolve an erroneously started target as well, so a regressed guard fails an assertion rather than hanging.
   if(f.executions.length>cases.length)f.executions.at(-1).resolve(E.run(task));await pending;
   assert.equal(f.executions.length,cases.length,stale+' during '+(authored?'authored':'generic')+' control-to-target handoff must not start manuscript work');assert.equal(f.app.getState().selected,selected);assert.equal(f.requests.filter(r=>r.options.method==='POST').length,0);
  }finally{f.app.destroy();}
 }
 console.log('PASS control handoff races: cancel/navigation/destroy after the final generic or authored control passes and before caller resumes cannot start the target.');
}
